import os
import hashlib
import argparse

def hash_file(file_path, hash_algo='sha256'):
    """Generate a hash for a file using the specified algorithm."""
    hasher = hashlib.new(hash_algo)
    with open(file_path, 'rb') as f:
        # Read and update hash string value in blocks of 4K
        for byte_block in iter(lambda: f.read(4096), b""):
            hasher.update(byte_block)
    return hasher.hexdigest()

def find_duplicates(directory, hash_algo='sha256'):
    """Find duplicate files in the specified directory based on content."""
    file_hashes = {}
    duplicates = []

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            file_hash = hash_file(file_path, hash_algo)
            if file_hash in file_hashes:
                file_hashes[file_hash].append(file_path)
            else:
                file_hashes[file_hash] = [file_path]

    for hash_list in file_hashes.values():
        if len(hash_list) > 1:
            duplicates.extend(hash_list)

    return duplicates

def main():
    parser = argparse.ArgumentParser(description='Find duplicate files based on content.')
    parser.add_argument('directory', type=str, help='The directory to search for duplicates.')
    parser.add_argument('--hash', type=str, default='sha256', choices=['md5', 'sha256'], help='The hashing algorithm to use (default: sha256).')
    args = parser.parse_args()

    duplicates = find_duplicates(args.directory, hash_algo=args.hash)
    if duplicates:
        print("Duplicate files found:")
        for duplicate in duplicates:
            print(duplicate)
    else:
        print("No duplicate files found.")

if __name__ == '__main__':
    main()
